{
  "name": "workboard",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js",
    "test": "node --test"
  }
}
import { validDueDate } from './public/dates.js';
import http from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { randomUUID } from 'node:crypto';
import { mkdirSync, readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = dirname(fileURLToPath(import.meta.url));
const databasePath = resolve(process.env.DB_PATH || 'data/workboard.sqlite');
mkdirSync(dirname(databasePath), { recursive: true });
const database = new DatabaseSync(databasePath);
database.exec('PRAGMA foreign_keys = ON');
database.exec(`CREATE TABLE IF NOT EXISTS projects (
  position INTEGER PRIMARY KEY AUTOINCREMENT,
  id TEXT NOT NULL UNIQUE,
  name TEXT NOT NULL
)`);
database.exec(`CREATE TABLE IF NOT EXISTS tasks (
  position INTEGER PRIMARY KEY AUTOINCREMENT,
  id TEXT NOT NULL UNIQUE,
  project_id TEXT NOT NULL REFERENCES projects(id),
  title TEXT NOT NULL,
  completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1))
)`);
if (!database.prepare('PRAGMA table_info(projects)').all().some(column => column.name === 'archived')) {
  database.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1))');
}
if (!database.prepare('PRAGMA table_info(tasks)').all().some(column => column.name === 'priority')) {
  database.exec("ALTER TABLE tasks ADD COLUMN priority TEXT NOT NULL DEFAULT 'Normal' CHECK (priority IN ('Low', 'Normal', 'High'))");
}
if (!database.prepare('PRAGMA table_info(projects)').all().some(column => column.name === 'default_task_priority')) {
  database.exec("ALTER TABLE projects ADD COLUMN default_task_priority TEXT NOT NULL DEFAULT 'Normal' CHECK (default_task_priority IN ('Low', 'Normal', 'High'))");
}
if (!database.prepare('PRAGMA table_info(tasks)').all().some(column => column.name === 'due_date')) {
  database.exec("ALTER TABLE tasks ADD COLUMN due_date TEXT NOT NULL DEFAULT ''");
}
if (!database.prepare('PRAGMA table_info(tasks)').all().some(column => column.name === 'notes')) {
  database.exec("ALTER TABLE tasks ADD COLUMN notes TEXT NOT NULL DEFAULT ''");
}
if (!database.prepare('PRAGMA table_info(tasks)').all().some(column => column.name === 'deleted')) {
  database.exec('ALTER TABLE tasks ADD COLUMN deleted INTEGER NOT NULL DEFAULT 0 CHECK (deleted IN (0, 1))');
}
// Keep positions even while tasks are away, so returns recover the established order.
database.exec(`CREATE TABLE IF NOT EXISTS task_project_positions (
  task_id TEXT NOT NULL REFERENCES tasks(id),
  project_id TEXT NOT NULL REFERENCES projects(id),
  position INTEGER NOT NULL,
  PRIMARY KEY (task_id, project_id),
  UNIQUE (project_id, position)
);
INSERT OR IGNORE INTO task_project_positions (task_id, project_id, position)
  SELECT id, project_id, position FROM tasks`);
const projectColumns = `SELECT p.id, p.name, p.archived, p.default_task_priority,
  (SELECT COUNT(*) FROM tasks t WHERE t.project_id = p.id AND t.deleted = 0) AS total,
  (SELECT COUNT(*) FROM tasks t WHERE t.project_id = p.id AND t.deleted = 0 AND t.completed = 1) AS completed
  FROM projects p`;
const listProjects = database.prepare(`${projectColumns} ORDER BY p.position`);
const findProject = database.prepare(`${projectColumns} WHERE p.id = ?`);
const updateProject = database.prepare('UPDATE projects SET archived = ? WHERE id = ?');
const renameProject = database.prepare('UPDATE projects SET name = ? WHERE id = ?');
const updateDefaultTaskPriority = database.prepare('UPDATE projects SET default_task_priority = ? WHERE id = ?');
const insertProject = database.prepare('INSERT INTO projects (id, name) VALUES (?, ?)');
const listTasks = database.prepare(`SELECT t.id, t.title, t.completed, t.priority, t.due_date, t.notes, t.deleted
  FROM tasks t JOIN task_project_positions p ON p.task_id = t.id AND p.project_id = t.project_id
  WHERE t.project_id = ? ORDER BY p.position`);
const findTask = database.prepare('SELECT id, title, completed, priority, due_date, notes, deleted FROM tasks WHERE project_id = ? AND id = ?');
const insertTask = database.prepare('INSERT INTO tasks (id, project_id, title, priority) VALUES (?, ?, ?, ?)');
const updateTask = database.prepare('UPDATE tasks SET completed = ? WHERE project_id = ? AND id = ?');
const renameTask = database.prepare('UPDATE tasks SET title = ? WHERE project_id = ? AND id = ?');
const updateTaskPriority = database.prepare('UPDATE tasks SET priority = ? WHERE project_id = ? AND id = ?');
const updateTaskDueDate = database.prepare('UPDATE tasks SET due_date = ? WHERE project_id = ? AND id = ?');
const updateTaskNotes = database.prepare('UPDATE tasks SET notes = ? WHERE project_id = ? AND id = ?');
const updateTaskDeleted = database.prepare('UPDATE tasks SET deleted = ? WHERE project_id = ? AND id = ?');
const moveTask = database.prepare('UPDATE tasks SET project_id = ? WHERE project_id = ? AND id = ?');
const rememberTaskPosition = database.prepare(`INSERT INTO task_project_positions (task_id, project_id, position)
  SELECT ?, ?, COALESCE(MAX(position), 0) + 1 FROM task_project_positions WHERE project_id = ?
  ON CONFLICT (task_id, project_id) DO NOTHING`);

function transaction(action) {
  database.exec('BEGIN');
  try {
    action();
    database.exec('COMMIT');
  } catch (error) {
    database.exec('ROLLBACK');
    throw error;
  }
}
const assets = new Map([
  ['/', ['public/index.html', 'text/html; charset=utf-8']],
  ['/dates.js', ['public/dates.js', 'text/javascript; charset=utf-8']],
  ['/app.js', ['public/app.js', 'text/javascript; charset=utf-8']],
  ['/style.css', ['public/style.css', 'text/css; charset=utf-8']],
]);

function json(response, status, body) {
  response.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
  response.end(JSON.stringify(body));
}

async function readJson(request) {
  let body = '';
  for await (const chunk of request) {
    body += chunk;
    if (Buffer.byteLength(body) > 65536) {
      throw Object.assign(new Error('Request is too large'), { status: 413 });
    }
  }
  try {
    return JSON.parse(body);
  } catch {
    throw Object.assign(new Error('Invalid JSON'), { status: 400 });
  }
}

function taskResult(task) {
  return { ...task, completed: Boolean(task.completed), deleted: Boolean(task.deleted) };
}

function projectResult(project) {
  return { ...project, archived: Boolean(project.archived) };
}

const server = http.createServer(async (request, response) => {
  try {
    const path = new URL(request.url, 'http://localhost').pathname;
    if (request.method === 'GET' && path === '/health') {
      return json(response, 200, { status: 'ok' });
    }
    if (request.method === 'GET' && path === '/api/projects') {
      return json(response, 200, listProjects.all().map(projectResult));
    }
    if (request.method === 'POST' && path === '/api/projects') {
      const input = await readJson(request);
      const name = typeof input?.name === 'string' ? input.name.trim() : '';
      if (!name) return json(response, 400, { error: 'Project name is required' });
      const project = { id: randomUUID(), name };
      insertProject.run(project.id, project.name);
      return json(response, 201, projectResult(findProject.get(project.id)));
    }
    const exportMatch = path.match(/^\/api\/projects\/([^/]+)\/export$/);
    if (request.method === 'GET' && exportMatch) {
      const project = findProject.get(exportMatch[1]);
      if (!project) return json(response, 404, { error: 'Project not found' });
      const document = {
        format: 'workboard-project',
        version: 1,
        project: {
          name: project.name,
          archived: Boolean(project.archived),
          defaultPriority: project.default_task_priority,
          tasks: listTasks.all(project.id).map(task => ({
            title: task.title,
            completed: Boolean(task.completed),
            priority: task.priority,
            dueDate: task.due_date,
            notes: task.notes.replace(/\r\n?/g, '\n'),
            deleted: Boolean(task.deleted),
          })),
        },
      };
      response.setHeader('Content-Disposition', 'attachment; filename="workboard-project.json"');
      return json(response, 200, document);
    }
    const tasksMatch = path.match(/^\/api\/projects\/([^/]+)\/tasks(?:\/([^/]+))?$/);
    if (tasksMatch) {
      const [, projectId, taskId] = tasksMatch;
      const project = findProject.get(projectId);
      if (!project) return json(response, 404, { error: 'Project not found' });
      if (request.method === 'GET' && !taskId) {
        return json(response, 200, listTasks.all(projectId).map(taskResult));
      }
      if (request.method === 'POST' && !taskId) {
        const input = await readJson(request);
        const currentProject = findProject.get(projectId);
        if (currentProject.archived) return json(response, 409, { error: 'Archived project is read-only' });
        const title = typeof input?.title === 'string' ? input.title.trim() : '';
        if (!title) return json(response, 400, { error: 'Task title is required' });
        const task = { id: randomUUID(), title, completed: false };
        transaction(() => {
          insertTask.run(task.id, projectId, task.title, currentProject.default_task_priority);
          rememberTaskPosition.run(task.id, projectId, projectId);
        });
        return json(response, 201, taskResult(findTask.get(projectId, task.id)));
      }
      if (request.method === 'PATCH' && taskId) {
        if (!findTask.get(projectId, taskId)) return json(response, 404, { error: 'Task not found' });
        const input = await readJson(request);
        if (findProject.get(projectId).archived) return json(response, 409, { error: 'Archived project is read-only' });
        if (input && Object.hasOwn(input, 'deleted')) {
          if (typeof input.deleted !== 'boolean') {
            return json(response, 400, { error: 'Deleted must be a boolean' });
          }
          updateTaskDeleted.run(Number(input.deleted), projectId, taskId);
          return json(response, 200, taskResult(findTask.get(projectId, taskId)));
        }
        if (findTask.get(projectId, taskId).deleted) {
          return json(response, 409, { error: 'Deleted task is read-only until restored' });
        }
        if (input && Object.hasOwn(input, 'destination_project_id')) {
          const destination = typeof input.destination_project_id === 'string'
            ? findProject.get(input.destination_project_id) : null;
          if (!destination || destination.id === projectId || destination.archived) {
            return json(response, 400, { error: 'Destination must be another active project' });
          }
          transaction(() => {
            rememberTaskPosition.run(taskId, destination.id, destination.id);
            moveTask.run(destination.id, projectId, taskId);
          });
          return json(response, 200, taskResult(findTask.get(destination.id, taskId)));
        }
        if (input && Object.hasOwn(input, 'notes')) {
          if (typeof input.notes !== 'string') {
            return json(response, 400, { error: 'Notes must be text' });
          }
          updateTaskNotes.run(input.notes, projectId, taskId);
          return json(response, 200, taskResult(findTask.get(projectId, taskId)));
        }
        if (input && Object.hasOwn(input, 'due_date')) {
          const dueDate = typeof input.due_date === 'string' ? input.due_date.trim() : null;
          if (dueDate === null || !validDueDate(dueDate)) {
            return json(response, 400, { error: 'Due date must be a valid YYYY-MM-DD date' });
          }
          updateTaskDueDate.run(dueDate, projectId, taskId);
          return json(response, 200, taskResult(findTask.get(projectId, taskId)));
        }
        if (input && Object.hasOwn(input, 'priority')) {
          if (!['Low', 'Normal', 'High'].includes(input.priority)) {
            return json(response, 400, { error: 'Priority must be Low, Normal, or High' });
          }
          updateTaskPriority.run(input.priority, projectId, taskId);
          return json(response, 200, taskResult(findTask.get(projectId, taskId)));
        }
        if (input && Object.hasOwn(input, 'title')) {
          const title = typeof input.title === 'string' ? input.title.trim() : '';
          if (!title) return json(response, 400, { error: 'Task title is required' });
          renameTask.run(title, projectId, taskId);
          return json(response, 200, taskResult(findTask.get(projectId, taskId)));
        }
        if (typeof input?.completed !== 'boolean') {
          return json(response, 400, { error: 'Completed must be a boolean' });
        }
        updateTask.run(Number(input.completed), projectId, taskId);
        return json(response, 200, taskResult(findTask.get(projectId, taskId)));
      }
    }
    const projectMatch = path.match(/^\/api\/projects\/([^/]+)$/);
    if (request.method === 'GET' && projectMatch) {
      const project = findProject.get(projectMatch[1]);
      return json(response, project ? 200 : 404, project ? projectResult(project) : { error: 'Project not found' });
    }
    if (request.method === 'PATCH' && projectMatch) {
      const projectId = projectMatch[1];
      if (!findProject.get(projectId)) return json(response, 404, { error: 'Project not found' });
      const input = await readJson(request);
      if (input && Object.hasOwn(input, 'default_task_priority')) {
        if (findProject.get(projectId).archived) return json(response, 409, { error: 'Archived project is read-only' });
        if (!['Low', 'Normal', 'High'].includes(input.default_task_priority)) {
          return json(response, 400, { error: 'Priority must be Low, Normal, or High' });
        }
        updateDefaultTaskPriority.run(input.default_task_priority, projectId);
        return json(response, 200, projectResult(findProject.get(projectId)));
      }
      if (input && Object.hasOwn(input, 'name')) {
        if (findProject.get(projectId).archived) return json(response, 409, { error: 'Archived project is read-only' });
        const name = typeof input.name === 'string' ? input.name.trim() : '';
        if (!name) return json(response, 400, { error: 'Project name is required' });
        renameProject.run(name, projectId);
        return json(response, 200, projectResult(findProject.get(projectId)));
      }
      if (typeof input?.archived !== 'boolean') {
        return json(response, 400, { error: 'Archived must be a boolean' });
      }
      updateProject.run(Number(input.archived), projectId);
      return json(response, 200, projectResult(findProject.get(projectId)));
    }
    const asset = assets.get(path) || (/^\/projects\/[^/]+$/.test(path) ? assets.get('/') : null);
    if (request.method === 'GET' && asset) {
      response.writeHead(200, { 'Content-Type': asset[1] });
      return response.end(readFileSync(resolve(root, asset[0])));
    }
    json(response, 404, { error: 'Not found' });
  } catch (error) {
    if (error.status) return json(response, error.status, { error: error.message });
    console.error(error);
    if (!response.headersSent) json(response, 500, { error: 'Something went wrong' });
    else response.end();
  }
});

server.listen(Number(process.env.PORT || 8080), '0.0.0.0', () => {
  console.log(`Workboard listening on port ${server.address().port}`);
});

for (const signal of ['SIGINT', 'SIGTERM']) {
  process.on(signal, () => server.close(() => {
    database.close();
    process.exit(0);
  }));
}
import { validDueDate } from './dates.js';

const projectsView = document.querySelector('#projects-view');
const projectView = document.querySelector('#project-view');
const form = document.querySelector('#project-form');
const input = document.querySelector('#project-name');
const alert = document.querySelector('#alert');
const list = document.querySelector('#project-list');
const projectFilter = document.querySelector('#project-filter');
const projectSearchForm = document.querySelector('#project-search-form');
const projectSearch = document.querySelector('#project-search');
const renameForm = document.querySelector('#rename-form');
const renameInput = document.querySelector('#new-project-name');
const renameAlert = document.querySelector('#rename-alert');
const taskForm = document.querySelector('#task-form');
const taskInput = document.querySelector('#task-title');
const taskAlert = document.querySelector('#task-alert');
const taskFilter = document.querySelector('#task-filter');
const priorityFilter = document.querySelector('#priority-filter');
const taskSearchForm = document.querySelector('#task-search-form');
const taskSearch = document.querySelector('#task-search');
const dueRangeForm = document.querySelector('#due-range-form');
const dueFrom = document.querySelector('#due-from');
const dueThrough = document.querySelector('#due-through');
const dueRangeAlert = document.querySelector('#due-range-alert');
const defaultTaskPriority = document.querySelector('#default-task-priority');
const taskList = document.querySelector('#task-list');
let projectId;
let savedDefaultTaskPriority;
let archived = false;
let projects = [];
let tasks = [];
let appliedDueFrom = '';
let appliedDueThrough = '';
let appliedProjectQuery = '';
let appliedTaskQuery = '';

function matchesSearch(text, query) {
  const normalize = value => value.replace(/[ \t]+/g, ' ')
    .replace(/[A-Z]/g, letter => letter.toLowerCase());
  return normalize(text).includes(normalize(query));
}

projectSearchForm.addEventListener('submit', event => {
  event.preventDefault();
  appliedProjectQuery = projectSearch.value.trim();
  projectSearch.value = appliedProjectQuery;
  renderProjects();
});

taskSearchForm.addEventListener('submit', event => {
  event.preventDefault();
  appliedTaskQuery = taskSearch.value.trim();
  taskSearch.value = appliedTaskQuery;
  renderTasks();
});

dueRangeForm.addEventListener('submit', event => {
  event.preventDefault();
  const from = dueFrom.value.trim();
  const through = dueThrough.value.trim();
  let error = '';
  if (!validDueDate(from) || !validDueDate(through)) {
    error = 'Due range must use valid YYYY-MM-DD dates';
  } else if (from && through && from > through) {
    error = 'Due from must not be after Due through';
  }
  dueRangeAlert.textContent = error;
  dueRangeAlert.hidden = !error;
  if (error) return;
  appliedDueFrom = from;
  appliedDueThrough = through;
  dueFrom.value = from;
  dueThrough.value = through;
  renderTasks();
});

async function request(path, options) {
  const response = await fetch(path, options);
  const body = await response.json();
  if (!response.ok) throw new Error(body.error || 'Unable to complete request');
  return body;
}

function showAlert(message) {
  alert.textContent = message;
  alert.hidden = !message;
}

function addProject(project) {
  const row = document.createElement('div');
  row.dataset.testid = 'project-row';
  row.className = 'project-row';
  const name = document.createElement('span');
  name.textContent = project.name;
  const summary = document.createElement('span');
  summary.dataset.testid = 'project-summary';
  summary.textContent = `${project.completed}/${project.total} completed`;
  const button = document.createElement('button');
  button.type = 'button';
  button.textContent = 'Open project';
  button.addEventListener('click', () => {
    window.location.href = `/projects/${encodeURIComponent(project.id)}`;
  });
  const archiveButton = document.createElement('button');
  archiveButton.type = 'button';
  archiveButton.textContent = project.archived ? 'Restore project' : 'Archive project';
  archiveButton.addEventListener('click', async () => {
    archiveButton.disabled = true;
    showAlert('');
    try {
      const saved = await request(`/api/projects/${project.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ archived: !project.archived }),
      });
      Object.assign(project, saved);
      renderProjects();
    } catch (error) {
      showAlert(error.message);
      archiveButton.disabled = false;
    }
  });
  row.append(name, summary, button, archiveButton);
  list.append(row);
}

function renderProjects() {
  list.replaceChildren();
  projects.filter(project => project.archived === (projectFilter.value === 'archived')
    && matchesSearch(project.name, appliedProjectQuery)).forEach(addProject);
}

projectFilter.addEventListener('change', renderProjects);

function showRenameAlert(message) {
  renameAlert.textContent = message;
  renameAlert.hidden = !message;
}

renameForm.addEventListener('submit', async (event) => {
  event.preventDefault();
  if (!projectId || archived) return;
  const name = renameInput.value.trim();
  if (!name) {
    showRenameAlert('Project name is required');
    return;
  }
  const button = renameForm.querySelector('button');
  button.disabled = true;
  showRenameAlert('');
  try {
    const project = await request(`/api/projects/${projectId}`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name }),
    });
    document.querySelector('#project-heading').textContent = project.name;
    document.title = `${project.name} · Workboard`;
    renameInput.value = '';
    renameInput.focus();
  } catch (error) {
    showRenameAlert(error.message);
  } finally {
    button.disabled = archived;
  }
});

function showTaskAlert(message) {
  taskAlert.textContent = message;
  taskAlert.hidden = !message;
}

function renderTasks() {
  taskList.replaceChildren();
  for (const task of tasks) {
    if (Boolean(task.deleted) !== (taskFilter.value === 'deleted')) continue;
    const readOnly = archived || Boolean(task.deleted);
    if (!matchesSearch(task.title, appliedTaskQuery)) continue;
    if (taskFilter.value === 'open' && task.completed) continue;
    if (taskFilter.value === 'completed' && !task.completed) continue;
    if (priorityFilter.value !== 'all' && task.priority !== priorityFilter.value) continue;
    if (appliedDueFrom || appliedDueThrough) {
      if (!task.due_date) continue;
      if (appliedDueFrom && task.due_date < appliedDueFrom) continue;
      if (appliedDueThrough && task.due_date > appliedDueThrough) continue;
    }
    const row = document.createElement('div');
    row.dataset.testid = 'task-row';
    row.className = 'task-row';
    const checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.checked = task.completed;
    checkbox.disabled = readOnly;
    checkbox.setAttribute('aria-label', `Complete ${task.title}`);
    const title = document.createElement('span');
    title.textContent = task.title;
    checkbox.addEventListener('change', async () => {
      if (readOnly) return;
      checkbox.disabled = true;
      showTaskAlert('');
      try {
        const saved = await request(`/api/projects/${projectId}/tasks/${task.id}`, {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ completed: checkbox.checked }),
        });
        task.completed = saved.completed;
        renderTasks();
      } catch (error) {
        checkbox.checked = task.completed;
        showTaskAlert(error.message);
      } finally {
        checkbox.disabled = readOnly;
      }
    });
    const taskRenameForm = document.createElement('form');
    taskRenameForm.className = 'create-fields';
    taskRenameForm.noValidate = true;
    const taskRenameInput = document.createElement('input');
    taskRenameInput.type = 'text';
    taskRenameInput.setAttribute('aria-label', 'New task title');
    taskRenameInput.disabled = readOnly;
    const taskRenameButton = document.createElement('button');
    taskRenameButton.type = 'submit';
    taskRenameButton.textContent = 'Rename task';
    taskRenameButton.disabled = readOnly;
    taskRenameForm.addEventListener('submit', async event => {
      event.preventDefault();
      if (readOnly) return;
      const newTitle = taskRenameInput.value.trim();
      if (!newTitle) {
        showTaskAlert('Task title is required');
        return;
      }
      taskRenameButton.disabled = true;
      taskRenameInput.disabled = true;
      showTaskAlert('');
      try {
        const saved = await request(`/api/projects/${projectId}/tasks/${task.id}`, {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ title: newTitle }),
        });
        task.title = saved.title;
        title.textContent = task.title;
        checkbox.setAttribute('aria-label', `Complete ${task.title}`);
        taskRenameInput.value = '';
        if (!matchesSearch(task.title, appliedTaskQuery)) renderTasks();
      } catch (error) {
        showTaskAlert(error.message);
      } finally {
        taskRenameButton.disabled = readOnly;
        taskRenameInput.disabled = readOnly;
      }
    });
    taskRenameForm.append(taskRenameInput, taskRenameButton);
    const priority = document.createElement('select');
    priority.setAttribute('aria-label', 'Task priority');
    priority.disabled = readOnly;
    for (const value of ['Low', 'Normal', 'High']) {
      const option = document.createElement('option');
      option.value = value;
      option.textContent = value;
      priority.append(option);
    }
    priority.value = task.priority;
    priority.addEventListener('change', async () => {
      if (readOnly) return;
      priority.disabled = true;
      showTaskAlert('');
      try {
        const saved = await request(`/api/projects/${projectId}/tasks/${task.id}`, {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ priority: priority.value }),
        });
        task.priority = saved.priority;
        renderTasks();
      } catch (error) {
        showTaskAlert(error.message);
      } finally {
        priority.value = task.priority;
        priority.disabled = readOnly;
      }
    });
    const dueDateForm = document.createElement('form');
    dueDateForm.className = 'create-fields';
    dueDateForm.noValidate = true;
    const dueDateInput = document.createElement('input');
    dueDateInput.type = 'text';
    dueDateInput.setAttribute('aria-label', 'Task due date');
    dueDateInput.value = task.due_date || '';
    dueDateInput.disabled = readOnly;
    const dueDateButton = document.createElement('button');
    dueDateButton.type = 'submit';
    dueDateButton.textContent = 'Save due date';
    dueDateButton.disabled = readOnly;
    dueDateForm.addEventListener('submit', async event => {
      event.preventDefault();
      if (readOnly) return;
      dueDateInput.disabled = true;
      dueDateButton.disabled = true;
      showTaskAlert('');
      try {
        const saved = await request(`/api/projects/${projectId}/tasks/${task.id}`, {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ due_date: dueDateInput.value.trim() }),
        });
        task.due_date = saved.due_date;
        dueDateInput.value = task.due_date;
        renderTasks();
      } catch (error) {
        showTaskAlert(error.message);
      } finally {
        dueDateInput.disabled = readOnly;
        dueDateButton.disabled = readOnly;
      }
    });
    dueDateForm.append(dueDateInput, dueDateButton);
    const moveForm = document.createElement('form');
    moveForm.className = 'create-fields';
    const destination = document.createElement('select');
    destination.setAttribute('aria-label', 'Destination project');
    const eligibleProjects = projects.filter(project => !project.archived && project.id !== projectId);
    for (const project of eligibleProjects) {
      const option = document.createElement('option');
      option.value = project.id;
      option.textContent = project.name;
      destination.append(option);
    }
    const moveButton = document.createElement('button');
    moveButton.type = 'submit';
    moveButton.textContent = 'Move task';
    destination.disabled = moveButton.disabled = readOnly || !eligibleProjects.length;
    moveForm.addEventListener('submit', async event => {
      event.preventDefault();
      if (readOnly || !eligibleProjects.length) return;
      destination.disabled = moveButton.disabled = true;
      showTaskAlert('');
      try {
        await request(`/api/projects/${projectId}/tasks/${task.id}`, {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ destination_project_id: destination.value }),
        });
        tasks = tasks.filter(candidate => candidate.id !== task.id);
        renderTasks();
      } catch (error) {
        showTaskAlert(error.message);
      } finally {
        destination.disabled = moveButton.disabled = readOnly || !eligibleProjects.length;
      }
    });
    moveForm.append(destination, moveButton);
    const notesForm = document.createElement('form');
    notesForm.className = 'create-fields';
    const notesInput = document.createElement('textarea');
    notesInput.setAttribute('aria-label', 'Task notes');
    notesInput.rows = 4;
    notesInput.value = task.notes || '';
    notesInput.disabled = readOnly;
    const notesButton = document.createElement('button');
    notesButton.type = 'submit';
    notesButton.textContent = 'Save notes';
    notesButton.disabled = readOnly;
    notesForm.addEventListener('submit', async event => {
      event.preventDefault();
      if (readOnly) return;
      notesInput.disabled = notesButton.disabled = true;
      showTaskAlert('');
      try {
        const saved = await request(`/api/projects/${projectId}/tasks/${task.id}`, {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ notes: notesInput.value }),
        });
        task.notes = saved.notes;
        renderTasks();
      } catch (error) {
        showTaskAlert(error.message);
      } finally {
        notesInput.disabled = notesButton.disabled = readOnly;
      }
    });
    notesForm.append(notesInput, notesButton);
    const deletionButton = document.createElement('button');
    deletionButton.type = 'button';
    deletionButton.textContent = task.deleted ? 'Restore task' : 'Delete task';
    deletionButton.disabled = archived;
    deletionButton.addEventListener('click', async () => {
      if (archived) return;
      deletionButton.disabled = true;
      showTaskAlert('');
      try {
        const saved = await request(`/api/projects/${projectId}/tasks/${task.id}`, {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ deleted: !task.deleted }),
        });
        Object.assign(task, saved);
        renderTasks();
      } catch (error) {
        showTaskAlert(error.message);
      } finally {
        deletionButton.disabled = archived;
      }
    });
    row.append(checkbox, title, taskRenameForm, priority, dueDateForm, moveForm, notesForm, deletionButton);
    taskList.append(row);
  }
}

taskFilter.addEventListener('change', renderTasks);
priorityFilter.addEventListener('change', renderTasks);

defaultTaskPriority.addEventListener('change', async () => {
  if (!projectId || archived) return;
  defaultTaskPriority.disabled = true;
  showTaskAlert('');
  try {
    const project = await request(`/api/projects/${projectId}`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ default_task_priority: defaultTaskPriority.value }),
    });
    savedDefaultTaskPriority = project.default_task_priority;
  } catch (error) {
    showTaskAlert(error.message);
  } finally {
    defaultTaskPriority.value = savedDefaultTaskPriority;
    defaultTaskPriority.disabled = archived;
  }
});

taskForm.addEventListener('submit', async (event) => {
  event.preventDefault();
  if (archived) return;
  const title = taskInput.value.trim();
  if (!title) {
    showTaskAlert('Task title is required');
    return;
  }
  const button = taskForm.querySelector('button');
  button.disabled = true;
  showTaskAlert('');
  try {
    const task = await request(`/api/projects/${projectId}/tasks`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ title }),
    });
    tasks.push(task);
    renderTasks();
    taskInput.value = '';
    taskInput.focus();
  } catch (error) {
    showTaskAlert(error.message);
  } finally {
    button.disabled = false;
  }
});

form.addEventListener('submit', async (event) => {
  event.preventDefault();
  const name = input.value.trim();
  if (!name) {
    showAlert('Project name is required');
    return;
  }
  const button = form.querySelector('button');
  button.disabled = true;
  showAlert('');
  try {
    const project = await request('/api/projects', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name }),
    });
    projects.push(project);
    renderProjects();
    input.value = '';
    input.focus();
  } catch (error) {
    showAlert(error.message);
  } finally {
    button.disabled = false;
  }
});

document.querySelector('#back-button').addEventListener('click', () => {
  window.location.href = '/';
});

async function initialize() {
  const match = window.location.pathname.match(/^\/projects\/([^/]+)$/);
  if (match) {
    projectsView.hidden = true;
    projectView.hidden = false;
    try {
      const project = await request(`/api/projects/${match[1]}`);
      projectId = project.id;
      const download = document.querySelector('#download-project');
      download.href = `/api/projects/${encodeURIComponent(projectId)}/export`;
      download.hidden = false;
      archived = Boolean(project.archived);
      savedDefaultTaskPriority = project.default_task_priority;
      defaultTaskPriority.value = savedDefaultTaskPriority;
      defaultTaskPriority.disabled = archived;
      document.querySelector('#archived-message').hidden = !archived;
      document.querySelector('#project-heading').textContent = project.name;
      document.title = `${project.name} · Workboard`;
      renameForm.hidden = false;
      renameInput.disabled = archived;
      renameForm.querySelector('button').disabled = archived;
      tasks = await request(`/api/projects/${projectId}/tasks`);
      projects = await request('/api/projects');
      renderTasks();
      document.querySelector('#task-controls').hidden = false;
      taskForm.querySelector('button').disabled = archived;
    } catch (error) {
      const projectError = document.querySelector('#project-error');
      projectError.textContent = error.message;
      projectError.hidden = false;
    }
  } else {
    form.querySelector('button').disabled = true;
    try {
      projects = await request('/api/projects');
      renderProjects();
    } catch (error) {
      showAlert(error.message);
    } finally {
      form.querySelector('button').disabled = false;
    }
  }
}

initialize();
